     6→/* Module creation */
     7→CirModule *cir_module_new(void) {
     8→    CirModule *m = (CirModule *)malloc(sizeof(CirModule));
     9→    if (!m) return NULL;
    10→
    11→    m->insts = (CirInst *)malloc(sizeof(CirInst) * 1024);
    12→    if (!m->insts) {
    13→        free(m);
    14→        return NULL;
    15→    }
    16→    m->inst_count = 0;
    17→    m->inst_cap = 1024;
    18→
    19→    m->strings = (char **)malloc(sizeof(char *) * 256);
    20→    if (!m->strings) {
    21→        free(m->insts);
    22→        free(m);
    23→        return NULL;
    24→    }
    25→    m->str_count = 0;
    26→    m->str_cap = 256;
    27→
    28→    m->next_label = 0;
    29→    return m;
    30→}
    31→
    32→/* Module deallocation */
    33→void cir_module_free(CirModule *m) {
    34→    if (!m) return;
    35→    if (m->insts) free(m->insts);
    36→    for (uint32_t i = 0; i < m->str_count; i++) {
    37→        if (m->strings[i]) free(m->strings[i]);
    38→    }
    39→    if (m->strings) free(m->strings);
    40→    free(m);
    41→}
    42→
    43→/* String table intern */
    44→uint32_t cir_intern_str(CirModule *m, const char *name) {
    45→    if (!m || !name) return 0;
    46→    for (uint32_t i = 0; i < m->str_count; i++) {
    47→        if (m->strings[i] && strcmp(m->strings[i], name) == 0) {
    48→            return i;
    49→        }
    50→    }
    51→    if (m->str_count >= m->str_cap) {
    52→        m->str_cap *= 2;
    53→        char **new_strings = (char **)realloc(m->strings, sizeof(char *) * m->str_cap);
    54→        if (!new_strings) return 0;
    55→        m->strings = new_strings;
    56→    }
    57→    m->strings[m->str_count] = (char *)malloc(strlen(name) + 1);
    58→    if (!m->strings[m->str_count]) return 0;
    59→    strcpy(m->strings[m->str_count], name);
    60→    return m->str_count++;
    61→}
    62→
    63→/* Emit instruction */
    64→CirRef cir_emit(CirModule *m, CirInst inst) {
    65→    if (!m) return CIR_REF_NULL;
    66→    if (m->inst_count >= m->inst_cap) {
    67→        m->inst_cap *= 2;
    68→        CirInst *new_insts = (CirInst *)realloc(m->insts, sizeof(CirInst) * m->inst_cap);
    69→        if (!new_insts) return CIR_REF_NULL;
    70→        m->insts = new_insts;
    71→    }
    72→    m->insts[m->inst_count] = inst;
    73→    return m->inst_count++;
    74→}
    75→
    76→/* Allocate new label */
    77→uint32_t cir_new_label(CirModule *m) {
    78→    if (!m) return 0;
    79→    return m->next_label++;
    80→}
    81→
    82→/* AstGen creation */
    83→AstGen *astgen_new(CirModule *m) {
    84→    AstGen *g = (AstGen *)malloc(sizeof(AstGen));
    85→    if (!g) return NULL;
    86→    g->module = m;
    87→    g->var_names = (char **)malloc(sizeof(char *) * 256);
    88→    if (!g->var_names) {
    89→        free(g);
    90→        return NULL;
    91→    }
    92→    g->var_ids = (uint32_t *)malloc(sizeof(uint32_t) * 256);
    93→    if (!g->var_ids) {
    94→        free(g->var_names);
    95→        free(g);
    96→        return NULL;
    97→    }
    98→    g->var_count = 0;
    99→    g->var_cap = 256;
   100→    g->break_label = 0;
   101→    g->continue_label = 0;
   102→    return g;
   103→}
   104→
   105→/* AstGen cleanup */
   106→void astgen_free(AstGen *g) {
   107→    if (!g) return;
   108→    if (g->var_names) free(g->var_names);
   109→    if (g->var_ids) free(g->var_ids);
   110→    free(g);
   111→}
   112→
   113→/* Helper: lookup variable */
   114→static uint32_t astgen_lookup_var(AstGen *g, const char *name) {
   115→    for (int i = 0; i < g->var_count; i++) {
   116→        if (strcmp(g->var_names[i], name) == 0) {
   117→            return g->var_ids[i];
   118→        }
   119→    }
   120→    return cir_intern_str(g->module, name);
   121→}
   122→
   123→/* Expression generation */
   124→CirRef astgen_expr(AstGen *g, Node *expr) {
   125→    if (!expr) return CIR_REF_NULL;
   126→
   127→    switch (expr->kind) {
   128→        case ND_INT_LIT: {
   129→            CirInst inst = {.op = CIR_LOAD_INT, .u.load_int.imm = expr->int_val};
   130→            return cir_emit(g->module, inst);
   131→        }
   132→        case ND_FLOAT_LIT: {
   133→            CirInst inst = {.op = CIR_LOAD_FLOAT, .u.load_float.imm = expr->float_val};
   134→            return cir_emit(g->module, inst);
   135→        }
   136→        case ND_STR_LIT: {
   137→            uint32_t str_idx = cir_intern_str(g->module, expr->str_val);
   138→            CirInst inst = {.op = CIR_LOAD_STR, .u.load_str.str_idx = str_idx};
   139→            return cir_emit(g->module, inst);
   140→        }
   141→        case ND_IDENT: {
   142→            uint32_t name_idx = astgen_lookup_var(g, expr->name);
   143→            CirInst inst = {.op = CIR_LOAD_VAR, .u.load_var.name_idx = name_idx};
   144→            return cir_emit(g->module, inst);
   145→        }
   146→        case ND_BINARY: {
   147→            CirRef lhs = astgen_expr(g, expr->left);
   148→            CirRef rhs = astgen_expr(g, expr->right);
   149→            int op_val = 0;
   150→            switch (expr->op) {
   151→                case TK_PLUS: op_val = 0; break;
   152→                case TK_MINUS: op_val = 1; break;
   153→                case TK_STAR: op_val = 2; break;
   154→                case TK_SLASH: op_val = 3; break;
   155→                case TK_EQ: op_val = 12; break;
   156→                case TK_NEQ: op_val = 13; break;
   157→                case TK_LT: op_val = 14; break;
   158→                case TK_AND: op_val = 18; break;
   159→                case TK_OR: op_val = 19; break;
   160→                default: op_val = 0;
   161→            }
   162→            CirInst inst = {.op = CIR_BINARY, .u.binary = {.op = op_val, .lhs = lhs, .rhs = rhs}};
   163→            return cir_emit(g->module, inst);
   164→        }
   165→        case ND_ASSIGN: {
   166→            CirRef rhs = astgen_expr(g, expr->right);
   167→            if (expr->left->kind == ND_IDENT) {
   168→                uint32_t name_idx = astgen_lookup_var(g, expr->left->name);
   169→                CirInst inst = {.op = CIR_STORE_VAR, .u.store_var = {.name_idx = name_idx, .value = rhs}};
   170→                return cir_emit(g->module, inst);
   171→            }
   172→            return rhs;
   173→        }
   174→        case ND_CALL: {
   175→            CirRef callee = astgen_expr(g, expr->left);
   176→            int arg_count = expr->child_count;
   177→            CirRef *args = NULL;
   178→            if (arg_count > 0) {
   179→                args = (CirRef *)malloc(sizeof(CirRef) * arg_count);
   180→                for (int i = 0; i < arg_count; i++) {
   181→                    args[i] = astgen_expr(g, expr->children[i]);
   182→                }
   183→            }
   184→            CirInst inst = {.op = CIR_CALL, .u.call = {.callee = callee, .args = args, .arg_count = arg_count}};
   185→            return cir_emit(g->module, inst);
   186→        }
   187→        default:
   188→            return CIR_REF_NULL;
   189→    }
   190→}
   191→
   192→/* Statement generation */
   193→void astgen_stmt(AstGen *g, Node *stmt) {
   194→    if (!stmt) return;
   195→
   196→    switch (stmt->kind) {
   197→        case ND_EXPR_STMT:
   198→            astgen_expr(g, stmt->left);
   199→            break;
   200→        case ND_RETURN: {
   201→            CirRef value = CIR_REF_NULL;
   202→            if (stmt->left) value = astgen_expr(g, stmt->left);
   203→            CirInst ret = {.op = CIR_RETURN, .u.ret.value = value};
   204→            cir_emit(g->module, ret);
   205→            break;
   206→        }
   207→        case ND_BLOCK:
   208→            for (int i = 0; i < stmt->child_count; i++) {
   209→                astgen_stmt(g, stmt->children[i]);
   210→            }
   211→            break;
   212→        default:
   213→            break;
   214→    }
   215→}
   216→
   217→/* Function generation */
   218→void astgen_func(AstGen *g, Node *func_def) {
   219→    if (!func_def || func_def->kind != ND_FUNC_DEF) return;
   220→    uint32_t name_idx = cir_intern_str(g->module, func_def->name);
   221→    int param_count = func_def->child_count;
   222→    CirInst func_begin = {.op = CIR_FUNC_BEGIN, .u.func_begin = {.name_idx = name_idx, .param_count = param_count}};
   223→    cir_emit(g->module, func_begin);
   224→    if (func_def->body) astgen_stmt(g, func_def->body);
   225→    CirInst func_end = {.op = CIR_FUNC_END};
   226→    cir_emit(g->module, func_end);
   227→}
   228→
   229→/* Program generation */
   230→void astgen_program(AstGen *g, Node *program) {
   231→    if (!program || program->kind != ND_PROGRAM) return;
   232→    for (int i = 0; i < program->child_count; i++) {
   233→        Node *decl = program->children[i];
   234→        if (decl->kind == ND_FUNC_DEF) {
   235→            astgen_func(g, decl);
   236→        }
   237→    }
   238→}
