   240→/* Debug output */
   241→static const char *cir_opcode_to_string(CirOpcode op) {
   242→    switch (op) {
   243→        case CIR_LOAD_INT: return "LOAD_INT";
   244→        case CIR_LOAD_FLOAT: return "LOAD_FLOAT";
   245→        case CIR_LOAD_STR: return "LOAD_STR";
   246→        case CIR_LOAD_VAR: return "LOAD_VAR";
   247→        case CIR_STORE_VAR: return "STORE_VAR";
   248→        case CIR_ADDR_OF: return "ADDR_OF";
   249→        case CIR_DEREF: return "DEREF";
   250→        case CIR_INDEX: return "INDEX";
   251→        case CIR_MEMBER: return "MEMBER";
   252→        case CIR_BINARY: return "BINARY";
   253→        case CIR_UNARY: return "UNARY";
   254→        case CIR_LABEL: return "LABEL";
   255→        case CIR_JMP: return "JMP";
   256→        case CIR_JMP_IF: return "JMP_IF";
   257→        case CIR_RETURN: return "RETURN";
   258→        case CIR_FUNC_BEGIN: return "FUNC_BEGIN";
   259→        case CIR_FUNC_END: return "FUNC_END";
   260→        case CIR_CALL: return "CALL";
   261→        case CIR_ARG: return "ARG";
   262→        case CIR_NOP: return "NOP";
   263→        default: return "UNKNOWN";
   264→    }
   265→}
   266→
   267→void cir_module_dump(CirModule *m) {
   268→    if (!m) return;
   269→    printf("=== CIR Module ===\n");
   270→    printf("Instructions: %u, Strings: %u\n", m->inst_count, m->str_count);
   271→    printf("\nInstructions:\n");
   272→    for (uint32_t i = 0; i < m->inst_count; i++) {
   273→        printf("  [%u] %s\n", i, cir_opcode_to_string(m->insts[i].op));
   274→    }
   275→}
