    61→/* 노드 생성 */
    62→Node *node_new(NodeKind kind, SourceLoc loc) {
    63→    Node *n = (Node *)malloc(sizeof(Node));
    64→    if (!n) return NULL;
    65→
    66→    n->kind = kind;
    67→    n->loc = loc;
    68→
    69→    n->left = n->right = NULL;
    70→    n->cond = n->then_body = n->else_body = NULL;
    71→    n->init = n->step = n->body = NULL;
    72→    n->type_node = NULL;
    73→
    74→    n->children = NULL;
    75→    n->child_count = 0;
    76→    n->child_cap = 0;
    77→
    78→    n->int_val = 0;
    79→    n->float_val = 0.0;
    80→    n->char_val = 0;
    81→    n->str_val = NULL;
    82→    n->name = NULL;
    83→
    84→    n->op = TK_UNKNOWN;
    85→    n->is_prefix = 0;
