   101→/* 노드 재귀 해제 */
   102→void node_free_recursive(Node *node) {
   103→    if (!node) return;
   104→
   105→    node_free_recursive(node->left);
   106→    node_free_recursive(node->right);
   107→    node_free_recursive(node->cond);
   108→    node_free_recursive(node->then_body);
   109→    node_free_recursive(node->else_body);
   110→    node_free_recursive(node->init);
   111→    node_free_recursive(node->step);
   112→    node_free_recursive(node->body);
   113→    node_free_recursive(node->type_node);
   114→
   115→    for (int i = 0; i < node->child_count; i++) {
   116→        node_free_recursive(node->children[i]);
   117→    }
   118→
   119→    node_free(node);
   120→}
