   122→/* 자식 노드 추가 */
   123→void node_add_child(Node *parent, Node *child) {
   124→    if (!parent || !child) return;
   125→
   126→    if (parent->child_count >= parent->child_cap) {
   127→        parent->child_cap = parent->child_cap == 0 ? 8 : parent->child_cap * 2;
   128→        Node **new_children = (Node **)realloc(parent->children, sizeof(Node *) * parent->child_cap);
   129→        if (!new_children) return;
   130→        parent->children = new_children;
   131→    }
   132→
   133→    parent->children[parent->child_count++] = child;
   134→}
