   136→/* AST 디버그 출력 */
   137→void ast_dump(Node *node, int indent) {
   138→    if (!node) return;
   139→
   140→    for (int i = 0; i < indent; i++) printf("  ");
   141→
   142→    printf("[%s]", node_kind_to_string(node->kind));
   143→
   144→    if (node->kind == ND_INT_LIT) {
   145→        printf(" = %lld\n", node->int_val);
   146→    } else if (node->kind == ND_FLOAT_LIT) {
   147→        printf(" = %f\n", node->float_val);
